#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        VolumePerLength::new(v, VolumePerLengthUnit::CubicMeterPerMeter),
        VolumePerLength::from_cubic_meters_per_meter(v)
    );
    assert_eq!(
        VolumePerLength::from_base(v).convert_to(VolumePerLengthUnit::CubicMeterPerMeter),
        VolumePerLength::from_base(v).as_cubic_meters_per_meter()
    );
    assert_eq!(
        VolumePerLength::new(v, VolumePerLengthUnit::LiterPerMeter),
        VolumePerLength::from_liters_per_meter(v)
    );
    assert_eq!(
        VolumePerLength::from_base(v).convert_to(VolumePerLengthUnit::LiterPerMeter),
        VolumePerLength::from_base(v).as_liters_per_meter()
    );
    assert_eq!(
        VolumePerLength::new(v, VolumePerLengthUnit::LiterPerKilometer),
        VolumePerLength::from_liters_per_kilometer(v)
    );
    assert_eq!(
        VolumePerLength::from_base(v).convert_to(VolumePerLengthUnit::LiterPerKilometer),
        VolumePerLength::from_base(v).as_liters_per_kilometer()
    );
    assert_eq!(
        VolumePerLength::new(v, VolumePerLengthUnit::LiterPerMillimeter),
        VolumePerLength::from_liters_per_millimeter(v)
    );
    assert_eq!(
        VolumePerLength::from_base(v).convert_to(VolumePerLengthUnit::LiterPerMillimeter),
        VolumePerLength::from_base(v).as_liters_per_millimeter()
    );
    assert_eq!(
        VolumePerLength::new(v, VolumePerLengthUnit::OilBarrelPerFoot),
        VolumePerLength::from_oil_barrels_per_foot(v)
    );
    assert_eq!(
        VolumePerLength::from_base(v).convert_to(VolumePerLengthUnit::OilBarrelPerFoot),
        VolumePerLength::from_base(v).as_oil_barrels_per_foot()
    );
    assert_eq!(
        VolumePerLength::new(v, VolumePerLengthUnit::CubicYardPerFoot),
        VolumePerLength::from_cubic_yards_per_foot(v)
    );
    assert_eq!(
        VolumePerLength::from_base(v).convert_to(VolumePerLengthUnit::CubicYardPerFoot),
        VolumePerLength::from_base(v).as_cubic_yards_per_foot()
    );
    assert_eq!(
        VolumePerLength::new(v, VolumePerLengthUnit::CubicYardPerUsSurveyFoot),
        VolumePerLength::from_cubic_yards_per_us_survey_foot(v)
    );
    assert_eq!(
        VolumePerLength::from_base(v).convert_to(VolumePerLengthUnit::CubicYardPerUsSurveyFoot),
        VolumePerLength::from_base(v).as_cubic_yards_per_us_survey_foot()
    );
    assert_eq!(
        VolumePerLength::new(v, VolumePerLengthUnit::UsGallonPerMile),
        VolumePerLength::from_us_gallons_per_mile(v)
    );
    assert_eq!(
        VolumePerLength::from_base(v).convert_to(VolumePerLengthUnit::UsGallonPerMile),
        VolumePerLength::from_base(v).as_us_gallons_per_mile()
    );
    assert_eq!(
        VolumePerLength::new(v, VolumePerLengthUnit::ImperialGallonPerMile),
        VolumePerLength::from_imperial_gallons_per_mile(v)
    );
    assert_eq!(
        VolumePerLength::from_base(v).convert_to(VolumePerLengthUnit::ImperialGallonPerMile),
        VolumePerLength::from_base(v).as_imperial_gallons_per_mile()
    );
}

#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [VolumePerLength; 9] = [
        VolumePerLength::const_new(1234.5, VolumePerLengthUnit::CubicMeterPerMeter),
        VolumePerLength::const_new(1234.5, VolumePerLengthUnit::LiterPerMeter),
        VolumePerLength::const_new(1234.5, VolumePerLengthUnit::LiterPerKilometer),
        VolumePerLength::const_new(1234.5, VolumePerLengthUnit::LiterPerMillimeter),
        VolumePerLength::const_new(1234.5, VolumePerLengthUnit::OilBarrelPerFoot),
        VolumePerLength::const_new(1234.5, VolumePerLengthUnit::CubicYardPerFoot),
        VolumePerLength::const_new(1234.5, VolumePerLengthUnit::CubicYardPerUsSurveyFoot),
        VolumePerLength::const_new(1234.5, VolumePerLengthUnit::UsGallonPerMile),
        VolumePerLength::const_new(1234.5, VolumePerLengthUnit::ImperialGallonPerMile),
    ];
    for (q, &unit) in AT_COMPILE_TIME.iter().zip(VolumePerLengthUnit::ALL) {
        assert_eq!(
            q.as_base().to_bits(),
            VolumePerLength::new(1234.5_f64, unit).as_base().to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in VolumePerLengthUnit::ALL {
            assert_eq!(
                VolumePerLength::const_new(v, unit).as_base().to_bits(),
                VolumePerLength::<f64>::new(v, unit).as_base().to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = VolumePerLength::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            VolumePerLength::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in VolumePerLengthUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        VolumePerLength::from_base(0.0).auto_unit().unit,
        VolumePerLengthUnit::CubicMeterPerMeter
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "m³/m".parse::<VolumePerLengthUnit>(),
        Ok(VolumePerLengthUnit::CubicMeterPerMeter)
    );
    assert_eq!(
        format!("2.5 {}", "m³/m").parse::<VolumePerLength>(),
        Ok(VolumePerLength::new(
            2.5,
            VolumePerLengthUnit::CubicMeterPerMeter
        ))
    );
    assert_eq!(
        "l/m".parse::<VolumePerLengthUnit>(),
        Ok(VolumePerLengthUnit::LiterPerMeter)
    );
    assert_eq!(
        format!("2.5 {}", "l/m").parse::<VolumePerLength>(),
        Ok(VolumePerLength::new(
            2.5,
            VolumePerLengthUnit::LiterPerMeter
        ))
    );
    assert_eq!(
        "l/km".parse::<VolumePerLengthUnit>(),
        Ok(VolumePerLengthUnit::LiterPerKilometer)
    );
    assert_eq!(
        format!("2.5 {}", "l/km").parse::<VolumePerLength>(),
        Ok(VolumePerLength::new(
            2.5,
            VolumePerLengthUnit::LiterPerKilometer
        ))
    );
    assert_eq!(
        "l/mm".parse::<VolumePerLengthUnit>(),
        Ok(VolumePerLengthUnit::LiterPerMillimeter)
    );
    assert_eq!(
        format!("2.5 {}", "l/mm").parse::<VolumePerLength>(),
        Ok(VolumePerLength::new(
            2.5,
            VolumePerLengthUnit::LiterPerMillimeter
        ))
    );
    assert_eq!(
        "bbl/ft".parse::<VolumePerLengthUnit>(),
        Ok(VolumePerLengthUnit::OilBarrelPerFoot)
    );
    assert_eq!(
        format!("2.5 {}", "bbl/ft").parse::<VolumePerLength>(),
        Ok(VolumePerLength::new(
            2.5,
            VolumePerLengthUnit::OilBarrelPerFoot
        ))
    );
    assert_eq!(
        "yd³/ft".parse::<VolumePerLengthUnit>(),
        Ok(VolumePerLengthUnit::CubicYardPerFoot)
    );
    assert_eq!(
        format!("2.5 {}", "yd³/ft").parse::<VolumePerLength>(),
        Ok(VolumePerLength::new(
            2.5,
            VolumePerLengthUnit::CubicYardPerFoot
        ))
    );
    assert_eq!(
        "yd³/ftUS".parse::<VolumePerLengthUnit>(),
        Ok(VolumePerLengthUnit::CubicYardPerUsSurveyFoot)
    );
    assert_eq!(
        format!("2.5 {}", "yd³/ftUS").parse::<VolumePerLength>(),
        Ok(VolumePerLength::new(
            2.5,
            VolumePerLengthUnit::CubicYardPerUsSurveyFoot
        ))
    );
    assert_eq!(
        "gal (U.S.)/mi".parse::<VolumePerLengthUnit>(),
        Ok(VolumePerLengthUnit::UsGallonPerMile)
    );
    assert_eq!(
        format!("2.5 {}", "gal (U.S.)/mi").parse::<VolumePerLength>(),
        Ok(VolumePerLength::new(
            2.5,
            VolumePerLengthUnit::UsGallonPerMile
        ))
    );
    assert_eq!(
        "gal (imp.)/mi".parse::<VolumePerLengthUnit>(),
        Ok(VolumePerLengthUnit::ImperialGallonPerMile)
    );
    assert_eq!(
        format!("2.5 {}", "gal (imp.)/mi").parse::<VolumePerLength>(),
        Ok(VolumePerLength::new(
            2.5,
            VolumePerLengthUnit::ImperialGallonPerMile
        ))
    );
    assert_eq!(
        "1 not-a-unit".parse::<VolumePerLength>(),
        Err(ParseError::UnknownUnit)
    );
}

